import type { ReactNode } from "react"

import {
  ScanLine,
  UserRoundCheck,
  UserRoundX,
  UsersRound,
  type LucideIcon,
} from "lucide-react"

import {
  Card,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import type { ReportsKpis } from "@/features/reports/panel"
import { SlidingNumber } from "@/components/motion-primitives/sliding-number"
import { formatNumber } from "@/lib/format"

interface KpiCardProps {
  label: string
  value: ReactNode
  icon: LucideIcon
  detail: string
}

function KpiCard({ label, value, icon: Icon, detail }: KpiCardProps) {
  return (
    <Card className="@container/card gap-4" data-print="block">
      <CardHeader>
        <CardDescription className="flex items-center gap-2">
          <Icon aria-hidden className="size-4" />
          {label}
        </CardDescription>
        <CardTitle className="text-2xl font-semibold tabular-nums @[16rem]/card:text-3xl">
          {value}
        </CardTitle>
      </CardHeader>
      <CardFooter className="text-sm text-muted-foreground text-pretty">
        {detail}
      </CardFooter>
    </Card>
  )
}

export function KpiCards({
  kpis,
  sessionDays,
}: {
  kpis: ReportsKpis
  sessionDays: number
}) {
  const dayLabel = `${formatNumber(sessionDays)} recorded day${sessionDays === 1 ? "" : "s"}`

  return (
    <section
      aria-label="Report key performance indicators"
      className="grid grid-cols-1 gap-4 @xl/main:grid-cols-2 @5xl/main:grid-cols-4"
    >
      <KpiCard
        label="Current Active Students"
        value={<SlidingNumber value={kpis.totalStudents} />}
        icon={UsersRound}
        detail={`${kpis.representedStudents} students have records in this range, including retained history.`}
      />
      <KpiCard
        label="Total Present"
        value={<SlidingNumber value={kpis.totalPresent} />}
        icon={UserRoundCheck}
        detail={`Time-ins recorded across ${dayLabel}, late arrivals included.`}
      />
      <KpiCard
        label="Total Absent"
        value={<SlidingNumber value={kpis.totalAbsent} />}
        icon={UserRoundX}
        detail={`Recorded absences across ${dayLabel}.`}
      />
      <KpiCard
        label="RFID Scans"
        value={<SlidingNumber value={kpis.rfidScans} />}
        icon={ScanLine}
        detail="Captured time-ins plus time-outs in this range; historical status values excluded."
      />
    </section>
  )
}
